# Create the Kafka topics
bash
kafka-topics.sh --create --topic ad-impressions --partitions 16 --replication-factor 3 --config retention.ms=604800000 --config min.insync.replicas=2 --config cleanup.policy=compact --bootstrap-server kafka:9092
kafka-topics.sh --create --topic ad-impressions-enriched --partitions 16 --replication-factor 3 --config retention.ms=604800000 --config min.insync.replicas=2 --config cleanup.policy=compact --bootstrap-server kafka:9092

# Flink configuration
